#include <cstdio>
#include <algorithm>
using namespace std;

int m, n, p, dp[505], cnt[505], dp2[505][505], tot[505][505], fac[505], invfac[505], tmp, zh;

int mypow(int a, int b) {
    int ans = 1;
    while (b > 0) {
        if (b & 1) ans = (long long)ans * a % p;
        a = (long long)a * a % p;
        b >>= 1;
    }
    return ans;
}

int C(int n, int m) {
    return (long long)fac[n] * invfac[m] % p * invfac[n - m] % p;
}

int sum(int x) {
    return (long long)x * (x + 1) / 2 % p;
}

int main() {
    scanf("%d%d%d", &n, &m, &p);
    fac[0] = 1;
    for (int i = 1; i <= 500; i++) {
        fac[i] = (long long)fac[i - 1] * i % p;
    }
    invfac[500] = mypow(fac[500], p - 2);
    for (int i = 499; i >= 0; i--) {
        invfac[i] = (long long)invfac[i + 1] * (i + 1) % p;
    }
    cnt[0] = 1; dp[0] = 0;
    cnt[1] = 2; dp[1] = 0;
    for (int i = 2; i <= m; i++) {
        for (int j = 1; j <= i; j++) {
            zh = C(i - 1, j - 1);
            tmp = (long long)cnt[j - 1] * cnt[i - j] % p * zh % p;
            dp[i] = (dp[i] + (long long)tmp * sum(j - 1) + (long long)zh * j % p * ((long long)dp[j - 1] * cnt[i - j] % p + (long long)dp[i - j] * cnt[j - 1] % p) % p) % p;
            cnt[i] = (cnt[i] + (long long)tmp * j) % p;
            dp[i] = (dp[i] + (long long)tmp * sum(i - j) + (long long)zh * (i - j + 1) % p * ((long long)dp[j - 1] * cnt[i - j] % p + (long long)dp[i - j] * cnt[j - 1] % p) % p) % p;
            cnt[i] = (cnt[i] + (long long)tmp * (i - j + 1)) % p;
        }
    }
    dp2[0][0] = 0; tot[0][0] = 1;
    for (int i = 1; i <= n; i++) {
        for (int j = 0; j <= min(m, i); j++) {
            dp2[i][j] = dp2[i - 1][j];
            tot[i][j] = tot[i - 1][j];
            for (int k = 1; k <= j; k++) {
                if (k < i) {
                    zh = C(j, k);
                    dp2[i][j] = (dp2[i][j] + (long long)dp[k] * zh % p * tot[i - k - 1][j - k] % p + (long long)dp2[i - k - 1][j - k] * zh % p * cnt[k]) % p;
                    tot[i][j] = (tot[i][j] + (long long)cnt[k] * tot[i - k - 1][j - k] % p * zh) % p;
                } else {
                    dp2[i][j] = (dp2[i][j] + dp[i]) % p;
                    tot[i][j] = (tot[i][j] + cnt[i]) % p;
                }
            }
        }
    }
    printf("%d\n", dp2[n][m]);
    return 0;
}
